// Hämta kommentarer
const comments = $input.first().json.data || [];

// FILTRERA BORT TOMMA KOMMENTARER
const validComments = comments.filter(c => c.message && c.message.trim().length > 0);

if (validComments.length === 0) {
  return []; // STOPPAR workflow
}

// Sortera efter datum (nyast först)
const sorted = validComments.sort((a, b) => 
  new Date(b.created_time) - new Date(a.created_time)
);

const latest = sorted[0];

return [{
  json: {
    commentId: latest.id,
    commentMessage: latest.message,
    commentTime: latest.created_time,
    fromName: latest.from?.name || 'Kund'
  }
}];

// Hämta resultat från Notion-sökningen
const notionResults = $input.all();
const commentData = $('3. Extrahera Senaste').first().json;

// DEBUG: Logga vad vi fick
console.log('Notion results count:', notionResults.length);
console.log('First result:', JSON.stringify(notionResults[0]?.json));

// Kolla om det finns matchande poster i Notion
// Notion-noden returnerar en array - om den har items med properties = redan besvarad
const hasExistingEntry = notionResults.some(item => {
  // Kolla om detta är en riktig Notion-post (har properties)
  return item.json && item.json.properties;
});

if (hasExistingEntry) {
  console.log('STOPPAR - Kommentar redan besvarad:', commentData.commentId);
  return []; // STOPPA - redan besvarad
}

// Ny kommentar - fortsätt
console.log('NY KOMMENTAR - fortsätter:', commentData.commentId);
return [{
  json: {
    commentId: commentData.commentId,
    commentMessage: commentData.commentMessage,
    commentTime: commentData.commentTime,
    fromName: commentData.fromName,
    isNew: true
  }
}];

// Hämta kommentar-info från tidigare steg
const commentData = $('5. Redan Besvarad?').first().json;

// Hämta knowledge base
const kbItems = $input.all().map(item => {
  const props = item.json.properties || {};
  let name = '';
  let desc = '';
  let price = '';

  for (const [key, val] of Object.entries(props)) {
    if (val.title && val.title[0]) name = val.title[0].plain_text || '';
    if (val.rich_text && val.rich_text[0]) {
      if (key.toLowerCase().includes('desc')) desc = val.rich_text[0].plain_text || '';
      if (key.toLowerCase().includes('price') || key.toLowerCase().includes('pris')) price = val.rich_text[0].plain_text || '';
    }
  }

  return name ? `${name}: ${desc} (${price})` : '';
}).filter(x => x.length > 3);

const knowledgeContext = kbItems.join('\n') || 'Probiotika 3-i-1: 359 kr. Calm & Relax: 359 kr. Hip & Joint: 359 kr.';

return [{
  json: {
    commentId: commentData.commentId,
    commentMessage: commentData.commentMessage,
    knowledgeContext: knowledgeContext
  }
}];
